import numpy as np
def fold(n,i,per=2*n):
    p=i%per; return p if p<n else per-p
def mirror_tile(a):
    n,m=a.shape
    R=np.rot90(a,2)
    OH,OW=2*n,2*m
    return np.array([[R[fold(n,i)][fold(m,j)] for j in range(OW)] for i in range(OH)])
